<script lang="ts">
  import { onMount } from "svelte";
  import { Barcode, Banknote, CreditCard, Expand, Keyboard, Minus, Moon, Plus, Printer, QrCode, ShoppingBasket, Sun, Trash2, UserRound, X } from "@lucide/svelte";
  import { cashStatus, cloudGeneratePix, cloudPaymentStatus, inTauri, listCustomers, listProducts, onBarcode, recordSale, searchByEan, searchProduct, printReceipt, verifyAdminPin } from "../lib/tauri";
  import { brl } from "../lib/format";
  import type { Customer, Product } from "../lib/types";

  type CartItem = Product & { quantity: number };
  type Category = "all" | "bebidas" | "mercearia" | "limpeza" | "outros";
  const categories: { id: Category; label: string; icon: string }[] = [
    { id: "all", label: "Todos", icon: "" }, { id: "bebidas", label: "Bebidas", icon: "🥤" },
    { id: "mercearia", label: "Mercearia", icon: "🥫" }, { id: "limpeza", label: "Limpeza", icon: "🧽" }, { id: "outros", label: "Outros", icon: "🛒" },
  ];
  const previewProducts: Product[] = [
    { id:1,updated_at:0,ean:"78900001",part_number:"BEB-001",description:"Cerveja Pilsen 350 ml",brand:"Commerce",price_brl_cents:550,stock_qty:42,min_stock:10,active:true },
    { id:2,updated_at:0,ean:"78900002",part_number:"ADE-002",description:"Vinho Tinto Suave",brand:"Adega",price_brl_cents:3000,stock_qty:18,min_stock:5,active:true },
    { id:3,updated_at:0,ean:"78900003",part_number:"MER-003",description:"Arroz Tipo 1 · 5 kg",brand:"Mercado",price_brl_cents:2890,stock_qty:24,min_stock:8,active:true },
    { id:4,updated_at:0,ean:"78900004",part_number:"BEB-004",description:"Água Tônica",brand:"Fresh",price_brl_cents:500,stock_qty:9,min_stock:12,active:true },
    { id:5,updated_at:0,ean:"78900005",part_number:"ADE-005",description:"Whisky 12 Anos",brand:"Reserva",price_brl_cents:12000,stock_qty:4,min_stock:3,active:true },
    { id:6,updated_at:0,ean:"78900006",part_number:"BEB-006",description:"Energético",brand:"Power",price_brl_cents:800,stock_qty:50,min_stock:10,active:true },
  ];
  let products = $state<Product[]>([]), cart = $state<CartItem[]>([]), query = $state(""), category = $state<Category>("all");
  let darkMode = $state(false);
  let storeName = $state("Mercadinho Martins"), storeLogo = $state("");
  let paymentOpen = $state(false), paymentMethod = $state("cash"), amountPaid = $state(""), busy = $state(false), message = $state("");
  let pixPayload=$state(""),pixIntentId=$state(""),pixProvider=$state(""),pixStatus=$state(""),paymentAuthorized=$state(false),cardAuthorization=$state(""),consumerDocument=$state("");
  let customers = $state<Customer[]>([]), customerOpen = $state(false), selectedCustomer = $state<Customer|null>(null), initialCash = $state<number|null>(null);
  let removalOpen=$state(false),adminPin=$state(""),removalError=$state(""),pendingRemoval=$state<{ean?:string;all?:boolean;decrement?:boolean;label:string}|null>(null);
  let printOpen=$state(false),completedSale=$state<{uuid:string;items:[string,number][];total:number;payment?:string;document?:string}|null>(null);
  let searchTimer: number | undefined, searchInput: HTMLInputElement;
  let total = $derived(cart.reduce((sum, item) => sum + Math.round(item.price_brl_cents * item.quantity), 0));
  let itemsCount = $derived(cart.reduce((sum, item) => sum + item.quantity, 0));
  let visibleProducts = $derived(products.filter((product) => category === "all" || productCategory(product) === category));
  let paidCents = $derived(Math.round((Number(amountPaid.replace(",", ".")) || 0) * 100));
  let change = $derived(Math.max(0, paidCents - total));

  function productCategory(product: Product): Category { const text=`${product.description} ${product.brand ?? ""}`.toLowerCase(); if(/cerveja|vinho|whisky|gin|energ|água|agua|tônica|tonica|bebida/.test(text))return "bebidas"; if(/sabão|sabao|limpeza|deterg|desinfet|papel/.test(text))return "limpeza"; if(/pão|pao|café|cafe|leite|arroz|feijão|feijao|massa|mercearia/.test(text))return "mercearia"; return "outros"; }
  function productImage(product: Product) { return product.image_url||`http://127.0.0.1:8088/assets/demo-product/${encodeURIComponent(product.ean)}`; }
  function imageFallback(event: Event) { (event.currentTarget as HTMLImageElement).style.display="none"; }
  function add(product: Product) { const current=cart.find((item)=>item.ean===product.ean), next=(current?.quantity??0)+1; if(product.stock_qty<=0||next>product.stock_qty){message=`Estoque insuficiente para ${product.description}`;return} cart=current?cart.map((item)=>item.ean===product.ean?{...item,quantity:item.quantity+1}:item):[...cart,{...product,quantity:1}]; query=""; searchInput?.focus(); }
  function quantity(ean:string,delta:number){if(delta<0){const item=cart.find(row=>row.ean===ean);if(item){requestRemoval({ean,decrement:true,label:`Reduzir ${item.description}`});return}}cart=cart.map((item)=>{if(item.ean!==ean)return item;const next=item.quantity+delta;if(next>item.stock_qty){message=`Limite de estoque: ${item.stock_qty}`;return item}return{...item,quantity:next}}).filter((item)=>item.quantity>0)}
  async function scan(code:string){const product=await searchByEan(code);if(product)add(product);else message=`Produto ${code} não encontrado`}
  function search(){clearTimeout(searchTimer);searchTimer=window.setTimeout(async()=>{products=query.trim()?await searchProduct(query):await listProducts(40);},90)}
  function requestRemoval(action:{ean?:string;all?:boolean;decrement?:boolean;label:string}){if(!cart.length)return;pendingRemoval=action;adminPin="";removalError="";removalOpen=true}
  async function authorizeRemoval(){if(!pendingRemoval)return;try{await verifyAdminPin(adminPin);if(pendingRemoval.all)cart=[];else if(pendingRemoval.ean&&pendingRemoval.decrement)cart=cart.map(item=>item.ean===pendingRemoval?.ean?{...item,quantity:item.quantity-1}:item).filter(item=>item.quantity>0);else if(pendingRemoval.ean)cart=cart.filter(item=>item.ean!==pendingRemoval?.ean);message="Alteração autorizada e registrada no atendimento.";removalOpen=false;pendingRemoval=null}catch(e){removalError=e instanceof Error?e.message:String(e)}}
  function clearCart(){requestRemoval({all:true,label:"Limpar todo o carrinho"})}
  async function answerPrint(print:boolean){const sale=completedSale;printOpen=false;if(print&&sale){try{await printReceipt(sale.uuid,sale.items,sale.total,storeName,sale.payment,sale.document,storeLogo);message="Comprovante enviado para impressão."}catch(e){message=e instanceof Error?e.message:"Falha ao imprimir; documento mantido na fila."}}completedSale=null}
  function fullscreen(){document.documentElement.requestFullscreen?.()}
  function selectPayment(method:string){paymentMethod=method;paymentAuthorized=false;if(method!=="pix"){pixPayload="";pixIntentId="";pixProvider="";pixStatus=""}}
  async function confirmPayment(){if(busy||!cart.length||(paymentMethod==="cash"&&paidCents<total))return;busy=true;try{if(paymentMethod==="pix"&&!pixPayload){const intent=await cloudGeneratePix(total);pixPayload=intent.qr_payload??"";pixIntentId=intent.id;pixProvider=intent.provider;pixStatus=intent.status;message="PIX Asaas gerado. Aguardando confirmação automática.";return}if(paymentMethod==="pix"&&pixProvider==="asaas"&&pixIntentId){const intent=await cloudPaymentStatus(pixIntentId);pixStatus=intent.status;if(intent.status!=="received")throw new Error("Pagamento PIX ainda não foi confirmado pelo Asaas");paymentAuthorized=true}if(paymentMethod!=="cash"&&!paymentAuthorized)throw new Error("Confirme o recebimento antes de concluir");if(paymentMethod==="credit"&&!cardAuthorization.trim())throw new Error("Informe a autorização da operadora");const extra=paymentMethod==="pix"?{confirmation:pixProvider==="asaas"?"webhook":"manual",provider:pixProvider,payment_intent_id:pixIntentId||undefined,pix_copy_paste:pixPayload}:paymentMethod==="credit"?{authorization_code:cardAuthorization.trim()}:undefined;const saleItems=cart.map((item)=>[`${item.quantity}x ${item.description}`,item.price_brl_cents*item.quantity] as [string,number]);const saleTotal=total;const sale=await recordSale(cart.map((item)=>({ean:item.ean,qty:item.quantity,price_brl_cents:item.price_brl_cents})),{method:paymentMethod,amount_brl_cents:total,extra},"default",consumerDocument);completedSale={uuid:sale.sale_uuid,items:saleItems,total:saleTotal};const sold=new Map(cart.map((item)=>[item.ean,item.quantity]));products=products.map((product)=>sold.has(product.ean)?{...product,stock_qty:product.stock_qty-(sold.get(product.ean)??0)}:product);message=`Venda concluída · ${brl(total)}`;cart=[];paymentOpen=false;printOpen=true;amountPaid="";paymentMethod="cash";pixPayload="";pixIntentId="";pixProvider="";pixStatus="";paymentAuthorized=false;cardAuthorization="";consumerDocument=""}catch(error){message=error instanceof Error?error.message:"Não foi possível concluir a venda"}finally{busy=false}}
  function toggleLocalTheme(){darkMode=!darkMode;window.localStorage.setItem("commercectrl.theme",darkMode?"dark":"light");document.documentElement.classList.toggle("dark",darkMode);window.dispatchEvent(new CustomEvent("commercectrl-theme",{detail:darkMode}))}
  onMount(()=>{darkMode=document.documentElement.classList.contains("dark");const theme=(event:Event)=>darkMode=(event as CustomEvent<boolean>).detail;window.addEventListener("commercectrl-theme",theme);if(!inTauri()){products=previewProducts;initialCash=20000;return()=>window.removeEventListener("commercectrl-theme",theme)}listProducts(40).then((rows)=>products=rows);listCustomers().then((rows)=>customers=rows).catch(()=>{});cashStatus().then((cash)=>initialCash=cash.open?cash.opening_brl_cents:null).catch(()=>{});let unlisten:()=>void=()=>undefined;onBarcode(scan).then((fn)=>unlisten=fn);const key=(event:KeyboardEvent)=>{if(event.key==="F2"){event.preventDefault();customerOpen=true}if(event.key==="F4"){event.preventDefault();clearCart()}if(event.key==="F6"&&cart.length){event.preventDefault();selectPayment("pix");paymentOpen=true}if(event.key==="F7"&&cart.length){event.preventDefault();selectPayment("credit");paymentOpen=true}if(event.key==="F8"&&cart.length){event.preventDefault();selectPayment("cash");paymentOpen=true}if(event.key==="F11"){event.preventDefault();fullscreen()}if(event.key==="Escape"){paymentOpen=false;customerOpen=false}if(paymentOpen&&event.key==="Enter"){event.preventDefault();confirmPayment()}};window.addEventListener("keydown",key);return()=>{unlisten();window.removeEventListener("keydown",key);window.removeEventListener("commercectrl-theme",theme)}});
  onMount(()=>{const apply=(branding:{name?:string;logo?:string})=>{storeName=branding.name||"Mercadinho Martins";storeLogo=branding.logo||"";const title=document.querySelector<HTMLElement>(".store-line h2");if(title)title.textContent=storeName;const host=document.querySelector<HTMLElement>(".store-id");let image=host?.querySelector<HTMLImageElement>(".client-logo");if(storeLogo&&host){if(!image){image=document.createElement("img");image.className="client-logo";host.prepend(image)}image.src=storeLogo;image.alt=`Logo ${storeName}`}else image?.remove()};try{const saved=JSON.parse(localStorage.getItem("commercectrl.client.branding")??"null");if(saved)apply(saved)}catch{}const changed=(event:Event)=>apply((event as CustomEvent<{name:string;logo:string}>).detail);window.addEventListener("commercectrl-branding",changed);return()=>window.removeEventListener("commercectrl-branding",changed)});
</script>

<section class:dark={darkMode} class="market-pos">
  <header class="pos-topbar"><div class="store-id"><div><div class="store-line"><h2>Mercadinho Martins</h2><span class="kiosk-status"><i></i> Caixa tátil · online</span></div><p>Matriz Centro · operação de caixa</p></div></div><div class="pos-metrics"><div><span>Caixa inicial</span><strong>{initialCash===null?"Caixa fechado":brl(initialCash)}</strong></div><div><span>Itens no atendimento</span><strong>{itemsCount} item{itemsCount===1?"":"s"}</strong></div></div><button class="pos-theme" onclick={toggleLocalTheme} title="Alternar tema">{#if darkMode}<Sun size={17}/>{:else}<Moon size={17}/>{/if}</button><button class="pos-fullscreen" onclick={fullscreen} title="Tela cheia F11"><Expand size={17}/><span>Tela cheia</span></button></header>
  <div class="pos-workspace">
    <section class="catalog-zone"><div class="scan-area"><div class="scan-input"><Barcode size={22}/><input bind:this={searchInput} bind:value={query} oninput={search} onkeydown={(event)=>event.key==="Enter"&&scan(query)} placeholder="Bipe o código ou toque para buscar..."/><button class="keyboard" title="Use o teclado físico ou leitor"><Keyboard size={18}/></button><button class="add-search" onclick={()=>query&&scan(query)}>Adicionar</button></div><div class="category-row">{#each categories as item}<button class:active={category===item.id} onclick={()=>category=item.id}>{item.icon} {item.label}</button>{/each}</div></div>{#if message}<button class="pos-notice" onclick={()=>message=""}>{message}<X size={15}/></button>{/if}<div class="catalog-caption"><strong>Catálogo rápido</strong><span>Toque em um produto para adicionar</span></div><div class="market-products">{#each visibleProducts as product}<button class="market-product" disabled={product.stock_qty<=0} onclick={()=>add(product)}><div class="product-visual"><img src={productImage(product)} alt={`Imagem ilustrativa de ${product.description}`} onerror={imageFallback}/><span>{product.description.slice(0,1)}</span>{#if product.stock_qty<product.min_stock}<small>Últimas un.</small>{/if}</div><strong>{product.description}</strong><small>{product.brand??product.part_number}</small><footer><b>{brl(product.price_brl_cents)}</b><em class:low={product.stock_qty<product.min_stock}>{product.stock_qty<=0?"Indisponível":`${product.stock_qty} un.`}</em></footer></button>{/each}</div></section>
    <section class="checkout-zone"><header class="cart-title"><div><b>{itemsCount}</b><h2>Carrinho atual</h2></div><button onclick={clearCart} disabled={!cart.length}><Trash2 size={15}/> Limpar <kbd>F4</kbd></button></header><div class="market-cart">{#if !cart.length}<div class="cart-ready"><ShoppingBasket size={45}/><strong>Caixa disponível</strong><p>Bipe o código de barras ou toque em um produto no catálogo.</p></div>{/if}{#each cart as item}<article class="market-cart-row"><div class="cart-avatar">{item.description.slice(0,1)}</div><div class="cart-product"><strong>{item.description}</strong><small>{brl(item.price_brl_cents)} un.</small></div><div class="market-qty"><button onclick={()=>quantity(item.ean,-1)}><Minus size={13}/></button><b>{item.quantity}</b><button onclick={()=>quantity(item.ean,1)}><Plus size={13}/></button></div><strong class="line-total">{brl(item.price_brl_cents*item.quantity)}</strong><button class="remove-line" onclick={()=>requestRemoval({ean:item.ean,label:`Remover ${item.description}`})} aria-label="Remover item"><X size={15}/></button></article>{/each}</div><div class="customer-strip"><div><UserRound size={17}/><span><small>Cliente vinculado</small><strong>{selectedCustomer?.name??"Consumidor balcão"}</strong></span></div><button onclick={()=>customerOpen=true}>Vincular <kbd>F2</kbd></button></div><footer class="checkout-total"><div class="summary-line"><span>Subtotal de produtos</span><b>{brl(total)}</b></div><div class="summary-line"><span>Desconto autorizado</span><b class="zero-discount">{brl(0)}</b></div><div class="payment-total"><span>Total a pagar</span><strong>{brl(total)}</strong></div><div class="payment-buttons"><button class="pix" disabled={!cart.length} onclick={()=>{selectPayment("pix");paymentOpen=true}}><QrCode size={21}/><span>PIX <kbd>F6</kbd></span></button><button class="card" disabled={!cart.length} onclick={()=>{selectPayment("credit");paymentOpen=true}}><CreditCard size={21}/><span>Cartão <kbd>F7</kbd></span></button><button class="cash" disabled={!cart.length} onclick={()=>{selectPayment("cash");paymentOpen=true}}><Banknote size={21}/><span>Dinheiro <kbd>F8</kbd></span></button></div></footer></section>
  </div>
</section>

{#if customerOpen}<div class="modal-backdrop"><section class="modal customer-modal" role="dialog" aria-modal="true"><div class="card-header"><div><h2>Vincular cliente</h2><p class="small muted">Histórico e identificação da venda.</p></div><button class="icon-button" onclick={()=>customerOpen=false}><X size={18}/></button></div><div class="customer-list"><button class:chosen={!selectedCustomer} onclick={()=>{selectedCustomer=null;customerOpen=false}}><span><strong>Consumidor balcão</strong><small>Venda sem identificação</small></span></button>{#each customers as customer}<button class:chosen={selectedCustomer?.id===customer.id} onclick={()=>{selectedCustomer=customer;customerOpen=false}}><span><strong>{customer.name}</strong><small>{customer.cpf_cnpj??customer.phone??"Cliente cadastrado"}</small></span></button>{/each}</div></section></div>{/if}
{#if paymentOpen}<div class="modal-backdrop" role="presentation"><section class="modal payment-modal" role="dialog" aria-modal="true"><div class="card-header"><div><h2>Finalizar atendimento</h2><p class="small muted">Total da venda: {brl(total)}</p></div><button class="icon-button" onclick={()=>paymentOpen=false}><X size={18}/></button></div><div class="card-body"><label>CPF na Nota Paulista (opcional)<input class="input" inputmode="numeric" maxlength="14" placeholder="000.000.000-00" bind:value={consumerDocument}/></label></div><div class="payment-options"><button class:active={paymentMethod==="pix"} onclick={()=>selectPayment("pix")}><QrCode size={28}/><span>PIX</span><kbd>F6</kbd></button><button class:active={paymentMethod==="credit"} onclick={()=>selectPayment("credit")}><CreditCard size={28}/><span>Cartão</span><kbd>F7</kbd></button><button class:active={paymentMethod==="cash"} onclick={()=>selectPayment("cash")}><Banknote size={28}/><span>Dinheiro</span><kbd>F8</kbd></button></div>{#if paymentMethod==="cash"}<div class="card-body"><label>Valor entregue<input class="input" type="number" step="0.01" bind:value={amountPaid} placeholder="0,00"/></label>{#if change>0}<p class="change">Troco: <strong>{brl(change)}</strong></p>{/if}</div>{:else if paymentMethod==="credit"}<div class="card-body payment-confirm"><label>Autorização da operadora<input class="input" required bind:value={cardAuthorization}/></label><label class="check"><input type="checkbox" bind:checked={paymentAuthorized}/> Confirmo que o cartão foi aprovado no terminal</label></div>{:else}<div class="card-body payment-confirm">{#if pixPayload}<label>PIX Copia e Cola<textarea readonly>{pixPayload}</textarea></label><button class="button secondary" onclick={()=>navigator.clipboard.writeText(pixPayload)}>Copiar código</button>{#if pixProvider==="asaas"}<p class="small muted">Status Asaas: <strong>{pixStatus}</strong>. Clique em confirmar para verificar.</p>{:else}<label class="check"><input type="checkbox" bind:checked={paymentAuthorized}/> Confirmei o crédito na conta da loja</label>{/if}{:else}<p class="small muted">A geração do PIX Asaas exige conexão com a internet.</p>{/if}</div>{/if}<div class="card-footer modal-actions"><button class="button secondary" onclick={()=>paymentOpen=false}>Cancelar</button><button class="button" disabled={busy||(paymentMethod==="cash"&&paidCents<total)} onclick={confirmPayment}>{busy?"Processando...":paymentMethod==="pix"&&!pixPayload?"Gerar PIX":paymentMethod==="pix"&&pixProvider==="asaas"?"Verificar e concluir":"Confirmar e concluir"}</button></div></section></div>{/if}
{#if removalOpen}<div class="modal-backdrop"><section class="modal"><div class="card-header"><div><h2>Autorização necessária</h2><p class="small muted">{pendingRemoval?.label}</p></div></div><div class="card-body"><label>Senha do administrador ou gerente<input class="input" type="password" inputmode="numeric" autofocus bind:value={adminPin} onkeydown={(e)=>e.key==="Enter"&&authorizeRemoval()}/></label>{#if removalError}<p class="notice danger">{removalError}</p>{/if}</div><div class="card-footer modal-actions"><button class="button secondary" onclick={()=>removalOpen=false}>Cancelar</button><button class="button" onclick={authorizeRemoval}>Autorizar retirada</button></div></section></div>{/if}
{#if printOpen}<div class="modal-backdrop"><section class="modal"><div class="card-header"><div><h2>Venda concluída</h2><p class="small muted">Deseja imprimir o comprovante de venda?</p></div><Printer size={20}/></div><div class="card-body"><p><strong>COMPROVANTE DE VENDA — NÃO É DOCUMENTO FISCAL</strong></p><p class="small muted">A impressora preferencial deste terminal será usada. Se estiver indisponível, a fila configurada do Windows será tentada.</p></div><div class="card-footer modal-actions"><button class="button secondary" onclick={()=>answerPrint(false)}>Não imprimir</button><button class="button" onclick={()=>answerPrint(true)}>Imprimir comprovante</button></div></section></div>{/if}

<style>
  .market-pos{height:100vh;min-height:640px;overflow:hidden;border:0;background:#f6f8f6;color:#1f2937;font-family:"Plus Jakarta Sans",Inter,sans-serif}.pos-topbar{height:78px;padding:12px 18px;display:flex;align-items:center;justify-content:space-between;gap:14px;background:rgba(255,255,255,.95);border-bottom:1px solid #e1e6e2}.store-id,.store-line,.pos-metrics,.cart-title>div,.customer-strip>div{display:flex;align-items:center}.store-id{gap:12px}.store-monogram{width:46px;height:46px;display:grid;place-items:center;border-radius:15px;background:#151b18;color:#72efb2;font:900 16px/1 Outfit,"Space Grotesk";box-shadow:0 0 0 4px #dff8eb}.store-line{gap:9px}.store-line h2{font:900 16px Outfit,"Space Grotesk"}.store-id p{margin-top:3px;font-size:10px;color:#7a857e;font-weight:650}.kiosk-status{display:inline-flex;align-items:center;gap:5px;padding:4px 8px;border:1px solid #c8edda;border-radius:99px;color:#057a4a;background:#ecfbf3;font-size:9px;font-weight:800;text-transform:uppercase}.kiosk-status i{width:6px;height:6px;border-radius:50%;background:#10b981}.pos-metrics{gap:8px;margin-left:auto}.pos-metrics>div{min-width:120px;padding:7px 11px;border:1px solid #e1e7e2;border-radius:12px;background:#f6f8f6}.pos-metrics span{display:block;font-size:8px;font-weight:800;letter-spacing:.06em;text-transform:uppercase;color:#839087}.pos-metrics strong{font:800 11px Outfit,"Space Grotesk"}.pos-theme,.pos-fullscreen{height:38px;display:flex;align-items:center;justify-content:center;border:1px solid #e1e7e2;border-radius:11px;background:#f5f7f5;color:#3f4a43;font-weight:800;font-size:11px}.pos-theme{width:38px;margin-left:4px}.pos-fullscreen{gap:7px;padding:0 11px}.pos-workspace{display:grid;grid-template-columns:minmax(0,7fr) minmax(380px,5fr);height:calc(100% - 78px)}.catalog-zone{min-width:0;display:flex;flex-direction:column;background:#f3f6f3;border-right:1px solid #e1e6e2}.scan-area{padding:14px;background:#fff;border-bottom:1px solid #e4e9e4}.scan-input{position:relative;di